"use client";
import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
  type HTMLAttributes,
  type CSSProperties,
} from "react";
import "./voice-player.css";

export type PlaybackGroup = Set<() => void>;
export const createPlaybackGroup = (): PlaybackGroup => new Set();
interface PlaybackState {
  playing: boolean;
  time: number;
  duration: number;
  rate: number;
  error: string;
  available: boolean;
  toggle: () => void;
  seek: (time: number) => void;
  setRate: (rate: number) => void;
}
const PlaybackContext = createContext<PlaybackState | null>(null);
export function useVoicePlayer() {
  const value = useContext(PlaybackContext);
  if (!value) throw new Error("Voice controls must be inside VoicePlayerRoot.");
  return value;
}
export interface VoicePlayerRootProps extends HTMLAttributes<HTMLDivElement> {
  src?: string;
  group?: PlaybackGroup;
  children: ReactNode;
  onPlaybackChange?: (playing: boolean) => void;
}
/** React owns the controls and audio element. Media state stays with that element.
 * Consumers can compose these controls or supply their own with useVoicePlayer. */
export function VoicePlayerRoot({
  src,
  group,
  children,
  onPlaybackChange,
  className = "",
  ...props
}: VoicePlayerRootProps) {
  const audio = useRef<HTMLAudioElement>(null);
  const [state, setState] = useState({
    playing: false,
    time: 0,
    duration: 0,
    rate: 1,
    error: "",
  });
  const callback = useRef(onPlaybackChange);
  callback.current = onPlaybackChange;
  const sync = () => {
    const a = audio.current;
    if (a)
      setState((s) => ({
        ...s,
        playing: !a.paused,
        time: a.currentTime,
        duration: Number.isFinite(a.duration) ? a.duration : 0,
        rate: a.playbackRate,
      }));
  };
  useEffect(() => {
    const a = audio.current!;
    const pause = () => a.pause();
    group?.add(pause);
    return () => {
      pause();
      group?.delete(pause);
    };
  }, [group]);
  useEffect(() => {
    setState({ playing: false, time: 0, duration: 0, rate: 1, error: "" });
  }, [src]);
  const fail = (error?: unknown) => {
    const name = error instanceof Error ? error.name : "";
    const message =
      name === "NotAllowedError"
        ? "Playback blocked. Press play to retry."
        : audio.current?.error?.code === 2
          ? "Unable to load audio. Press play to retry."
          : "Audio unavailable. Check the source and try again.";
    setState((s) => ({ ...s, error: message }));
  };
  const toggle = async () => {
    const a = audio.current;
    if (!a || !src) return;
    if (!a.paused) {
      a.pause();
      return;
    }
    setState((s) => ({ ...s, error: "" }));
    group?.forEach((pause) => pause());
    if (a.error) a.load();
    try {
      await a.play();
    } catch (error) {
      fail(error);
    }
  };
  return (
    <PlaybackContext.Provider
      value={{
        ...state,
        available: !!src,
        toggle,
        seek: (time) => {
          const a = audio.current;
          if (a && state.duration) {
            a.currentTime = Math.max(0, Math.min(state.duration, time));
            sync();
          }
        },
        setRate: (rate) => {
          if (audio.current) {
            audio.current.playbackRate = rate;
            sync();
          }
        },
      }}
    >
      <div
        {...props}
        className={`roc-voice ${className}`}
        data-state={
          state.error
            ? "error"
            : state.playing
              ? "playing"
              : src
                ? "ready"
                : "empty"
        }
      >
        <audio
          ref={audio}
          src={src}
          preload="metadata"
          hidden
          onPlay={() => {
            sync();
            callback.current?.(true);
          }}
          onPause={() => {
            sync();
            callback.current?.(false);
          }}
          onEnded={sync}
          onTimeUpdate={sync}
          onDurationChange={sync}
          onLoadedMetadata={sync}
          onRateChange={sync}
          onError={() => fail()}
        />
        {children}
        {state.error && (
          <span className="roc-voice-error" role="alert">
            {state.error}
          </span>
        )}
      </div>
    </PlaybackContext.Provider>
  );
}
const timeLabel = (seconds: number) =>
  `${Math.floor(seconds / 60)}:${String(Math.floor(seconds % 60)).padStart(2, "0")}`;
export function VoicePlayButton() {
  const s = useVoicePlayer();
  return (
    <button
      type="button"
      className="roc-voice-play"
      aria-label={s.playing ? "Pause audio" : "Play audio"}
      disabled={!s.available}
      onClick={s.toggle}
    >
      <span
        aria-hidden="true"
        className="roc-voice-glyph"
        data-state={s.playing ? "inactive" : "active"}
      >
        ▶
      </span>
      <span
        aria-hidden="true"
        className="roc-voice-glyph"
        data-state={s.playing ? "active" : "inactive"}
      >
        Ⅱ
      </span>
    </button>
  );
}
export function VoiceSeek() {
  const s = useVoicePlayer();
  return (
    <input
      className="roc-voice-seek"
      type="range"
      aria-label="Playback position"
      aria-valuetext={`${timeLabel(s.time)} of ${timeLabel(s.duration)}`}
      min={0}
      max={s.duration || 1}
      step={0.01}
      value={s.time}
      disabled={!s.duration}
      onChange={(e) => s.seek(Number(e.target.value))}
      style={
        {
          "--roc-progress": s.duration ? s.time / s.duration : 0,
        } as CSSProperties
      }
    />
  );
}
export function VoiceTime() {
  const s = useVoicePlayer();
  return (
    <span className="roc-voice-time">
      {s.available ? timeLabel(s.time || s.duration) : "No audio"}
    </span>
  );
}
export function VoiceRate({ rates = [1, 1.5, 2] }: { rates?: number[] }) {
  const s = useVoicePlayer();
  return (
    <button
      type="button"
      className="roc-voice-rate"
      aria-label={`Playback speed, ${s.rate} times`}
      disabled={!s.available || !rates.length}
      onClick={() =>
        s.setRate(rates[(rates.indexOf(s.rate) + 1) % rates.length])
      }
    >
      {s.rate}×
    </button>
  );
}
export interface VoicePlayerProps
  extends Omit<VoicePlayerRootProps, "children"> {
  label?: string;
}
export function VoicePlayer({
  label = "Audio player",
  ...props
}: VoicePlayerProps) {
  return (
    <VoicePlayerRoot role="group" aria-label={label} {...props}>
      <VoicePlayButton />
      <VoiceSeek />
      <VoiceTime />
      <VoiceRate />
    </VoicePlayerRoot>
  );
}

@import "./surface.css";
.roc-voice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  width: 100%;
  padding: 14px;
  background: var(--roc-paper, #fcfbf8);
  border: 1px solid var(--roc-line, #e3e1da);
  border-radius: var(--roc-radius, 12px);
}
.roc-voice button {
  border: 0;
  background: var(--roc-subtle, #eaece5);
  border-radius: 50%;
  corner-shape: round;
  min-width: 34px;
  height: 34px;
  font-size: 12px;
  flex: none;
}
.roc-voice .roc-voice-rate {
  border-radius: var(--roc-radius, 8px);
  background: transparent;
  min-width: 30px;
}
.roc-voice-seek {
  flex: 1;
  min-width: 20px;
  width: 0;
  accent-color: var(--roc-accent, #667e68);
  height: 3px;
}
.roc-voice-time {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.roc-voice-error {
  flex-basis: 100%;
  font-size: 12px;
  line-height: 1.5;
  color: var(--roc-error, #9d4935);
}
.roc-voice button:disabled {
  opacity: 0.4;
}
/* Play and pause share one slot and cross-fade with a small blur and scale. */
.roc-voice .roc-voice-play {
  display: inline-grid;
  place-items: center;
}
.roc-voice-glyph {
  grid-area: 1 / 1;
  transition:
    opacity 250ms ease-in-out,
    transform 250ms ease-in-out,
    filter 250ms ease-in-out;
}
.roc-voice-glyph[data-state="inactive"] {
  opacity: 0;
  transform: scale(0.25);
  filter: blur(2px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-voice-glyph {
    transition: none;
  }
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.roc-image-viewport:focus-visible,
.roc-page-book:focus-visible,
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
@media (forced-colors: active) {
  .roc-image-viewport:focus-visible,
  .roc-page-book:focus-visible,
  :where(
      .roc-expand,
      .roc-folder,
      .roc-sources,
      .roc-lanes,
      .roc-tabs,
      .roc-card-preview,
      .roc-image-viewport,
      .roc-voice,
      .roc-selection-toolbar,
      .roc-page-book,
      .roc-source-tray
    )
    button:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}

/* ROC owns motion; Base UI owns interaction and portal presence. */
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
